cd /workspace && node -e "
const code = require('fs').readFileSync('App.js', 'utf8');

// Check for syntax errors
try {
  new Function(code);
  console.log('✅ JavaScript syntax is valid');
} catch (e) {
  console.log('❌ Syntax error:', e.message);
}

// Check that buildProviders is defined
if (code.includes('function buildProviders')) {
  console.log('✅ buildProviders function exists');
}

// Check that formatProviderLabel is defined  
if (code.includes('function formatProviderLabel')) {
  console.log('✅ formatProviderLabel function exists');
}

// Check that PROVIDERS.map uses provider.key
if (code.includes('key={provider.key}')) {
  console.log('✅ Provider key rendering is correct');
}
"

